// ==UserScript==
// @name         API Key Test
// @namespace    api-key-test
// @version      1.0
// @match        https://www.torn.com/*
// @run-at       document-end
// ==/UserScript==

(function () {
    "use strict";

    const testKey = "###PDA-APIKEY###";

    console.log(
        "[API Key Test] Placeholder replaced:",
        /^[a-f0-9]{16}$/i.test(testKey)
    );
})();

// ==UserScript==
// @name         TornPDA Crime Reward Values
// @namespace    tornpda-crime-reward-values
// @version      4.4.0
// @description  Automatically displays crime reward market values in a compact top popup.
// @match        https://www.torn.com/*
// @run-at       document-end
// @grant        none
// ==/UserScript==

(function () {
    "use strict";

    const API_KEY = "###PDA-APIKEY###";
    const CACHE_KEY = "tornpda_crime_item_prices_v1";
    const CACHE_TTL = 24 * 60 * 60 * 1000;

    const RESULT_SELECTOR = ".outcomeReward___aVKEh";
    const ITEM_SELECTOR = ".rewards___m4tv6 img.torn-item";
    const POPUP_ID = "crv-popup";
    const STYLE_ID = "crv-popup-style";

    let prices = {};
    let pricesReady = false;
    let priceError = "";
    let activeSection = null;
    let refreshScheduled = false;

    const processed = new WeakMap();

    // ---------- Compact popup styling ----------

    if (!document.getElementById(STYLE_ID)) {
        const style = document.createElement("style");
        style.id = STYLE_ID;

        style.textContent = `
            #${POPUP_ID} {
                position: fixed !important;
                z-index: 2147483647 !important;
                top: max(4px, env(safe-area-inset-top)) !important;
                left: 50% !important;
                transform: translateX(-50%) !important;
                width: calc(100% - 12px) !important;
                max-width: 340px !important;
                max-height: 20vh !important;
                overflow-y: auto !important;
                overscroll-behavior: contain !important;
                box-sizing: border-box !important;
                padding: 4px 7px !important;
                border: 1px solid #68788a !important;
                border-radius: 7px !important;
                background: #202630 !important;
                color: #f1f4f8 !important;
                box-shadow: 0 2px 7px rgba(0,0,0,.4) !important;
                font-family: Arial, sans-serif !important;
                font-size: 11px !important;
                line-height: 1.2 !important;
                pointer-events: auto !important;
            }

            #${POPUP_ID} * {
                box-sizing: border-box !important;
            }

            #${POPUP_ID} .crv-header {
                display: flex;
                align-items: center;
                justify-content: space-between;
                gap: 6px;
                margin: 0 0 2px;
                padding: 0 0 3px;
                border-bottom: 1px solid #485361;
            }

            #${POPUP_ID} .crv-heading {
                color: #fff;
                font-size: 12px;
                line-height: 1.2;
                font-weight: 700;
            }

            #${POPUP_ID} .crv-close {
                flex: 0 0 auto;
                min-width: 25px;
                min-height: 24px;
                border: 0;
                border-radius: 4px;
                padding: 1px 6px;
                background: #3b4654;
                color: #fff;
                font-size: 17px;
                line-height: 1;
                cursor: pointer;
            }

            #${POPUP_ID} .crv-line,
            #${POPUP_ID} .crv-total {
                display: flex;
                justify-content: space-between;
                align-items: center;
                gap: 6px;
                width: 100%;
                padding: 1px 0;
                line-height: 1.2;
            }

            #${POPUP_ID} .crv-name {
                flex: 1 1 auto;
                min-width: 0;
                overflow-wrap: anywhere;
                color: #e4eaf0;
            }

            #${POPUP_ID} .crv-price {
                flex: 0 0 auto;
                max-width: 48%;
                overflow-wrap: anywhere;
                text-align: right;
                color: #8fe0a0;
                font-weight: 700;
            }

            #${POPUP_ID} .crv-total {
                margin-top: 2px;
                padding-top: 3px;
                border-top: 1px solid #485361;
                font-weight: 700;
            }

            #${POPUP_ID} .crv-missing {
                color: #ffcc80;
            }
        `;

        document.head.appendChild(style);
    }

    function money(value) {
        return "$" + Math.round(value).toLocaleString("en-US");
    }

    // ---------- Cached API prices ----------

    function readCache() {
        try {
            const data = JSON.parse(
                localStorage.getItem(CACHE_KEY) || "null"
            );

            if (
                data &&
                data.prices &&
                data.time &&
                Date.now() - data.time < CACHE_TTL
            ) {
                return data.prices;
            }
        } catch (_) {}

        return null;
    }

    async function loadPrices() {
        const cached = readCache();

        if (cached) {
            prices = cached;
            pricesReady = true;
            updatePopup();
            return;
        }

        if (!API_KEY || API_KEY.includes("###")) {
            priceError = "API key was not injected";
            pricesReady = true;
            updatePopup();
            return;
        }

        try {
            const response = await fetch(
                "https://api.torn.com/torn/?selections=items&key=" +
                encodeURIComponent(API_KEY)
            );

            if (!response.ok) {
                throw new Error("HTTP " + response.status);
            }

            const data = await response.json();

            if (data.error) {
                throw new Error(
                    "Torn API error " + data.error.code
                );
            }

            const fresh = {};

            for (const id in (data.items || {})) {
                const raw = data.items[id].market_value;
                const value = Number(raw);

                if (
                    raw !== null &&
                    raw !== undefined &&
                    raw !== "" &&
                    Number.isFinite(value) &&
                    value > 0
                ) {
                    fresh[id] = value;
                }
            }

            prices = fresh;

            try {
                localStorage.setItem(
                    CACHE_KEY,
                    JSON.stringify({
                        time: Date.now(),
                        prices: prices
                    })
                );
            } catch (_) {}
        } catch (error) {
            priceError = error.message || "Unable to load prices";
        }

        pricesReady = true;
        updatePopup();
    }

    // ---------- Read reward items ----------

    function getRewards(section) {
        const found = new Map();

        section.querySelectorAll(ITEM_SELECTOR).forEach(img => {
            const src = img.getAttribute("src") || "";
            const match = src.match(/\/items\/(\d+)\//);

            if (!match) return;

            const id = match[1];
            const alt = (img.getAttribute("alt") || "").trim();
            const quantityMatch = alt.match(/,\s*(\d+)\s*$/);
            const tile = img.closest(
                ".baseItemTileWrapper___tV9VZ"
            );

            let quantity = quantityMatch
                ? parseInt(quantityMatch[1], 10)
                : 1;

            if (!quantityMatch && tile) {
                const counter = tile.querySelector(
                    ".tileCounterText___M9kgO"
                );

                const parsed = counter
                    ? parseInt(counter.textContent.trim(), 10)
                    : 1;

                if (Number.isFinite(parsed) && parsed > 0) {
                    quantity = parsed;
                }
            }

            const name = quantityMatch
                ? alt.replace(/,\s*\d+\s*$/, "").trim()
                : alt || "Item #" + id;

            if (found.has(id)) {
                found.get(id).quantity += quantity;
            } else {
                found.set(id, {
                    id,
                    name,
                    quantity
                });
            }
        });

        return Array.from(found.values());
    }

    function signature(rewards) {
        return rewards
            .map(item => item.id + ":" + item.quantity)
            .sort()
            .join("|");
    }
    // ---------- Popup ----------

    function closePopup() {
        document.getElementById(POPUP_ID)?.remove();
        activeSection = null;
    }

    function addLine(parent, nameText, valueText, missing = false) {
        const row = document.createElement("div");
        row.className = "crv-line";

        const name = document.createElement("span");
        name.className = "crv-name";
        name.textContent = nameText;

        const value = document.createElement("span");
        value.className = missing
            ? "crv-missing"
            : "crv-price";
        value.textContent = valueText;

        row.append(name, value);
        parent.appendChild(row);
    }

    function renderPopup() {
        if (!activeSection || !activeSection.isConnected) {
            closePopup();
            return;
        }

        const rewards = getRewards(activeSection);

        if (!rewards.length) {
            closePopup();
            return;
        }

        let popup = document.getElementById(POPUP_ID);

        if (!popup) {
            popup = document.createElement("div");
            popup.id = POPUP_ID;
            popup.setAttribute("role", "dialog");
            popup.setAttribute(
                "aria-label",
                "Reward market values"
            );
            document.body.appendChild(popup);
        }

        popup.replaceChildren();

        const header = document.createElement("div");
        header.className = "crv-header";

        const heading = document.createElement("div");
        heading.className = "crv-heading";
        heading.textContent = "Reward Values";

        const close = document.createElement("button");
        close.className = "crv-close";
        close.type = "button";
        close.textContent = "×";
        close.setAttribute(
            "aria-label",
            "Close reward values"
        );
        close.addEventListener("click", closePopup);

        header.append(heading, close);
        popup.appendChild(header);

        if (!pricesReady) {
            const loading = document.createElement("div");
            loading.textContent = "Loading prices…";
            popup.appendChild(loading);
            return;
        }

        if (priceError && !Object.keys(prices).length) {
            const error = document.createElement("div");
            error.className = "crv-missing";
            error.textContent = "Prices unavailable: " + priceError;
            popup.appendChild(error);
            return;
        }

        let total = 0;
        let missing = false;

        rewards.forEach(item => {
            const price = prices[item.id];

            const name = item.name +
                (item.quantity > 1
                    ? " ×" + item.quantity
                    : "");

            if (Number.isFinite(price) && price > 0) {
                addLine(
                    popup,
                    name,
                    money(price * item.quantity)
                );

                total += price * item.quantity;
            } else {
                addLine(
                    popup,
                    name,
                    "Unavailable",
                    true
                );

                missing = true;
            }
        });

        const totalRow = document.createElement("div");
        totalRow.className = "crv-total";

        const totalLabel = document.createElement("span");
        totalLabel.className = "crv-name";
        totalLabel.textContent = missing
            ? "Known value"
            : "Total value";

        const totalAmount = document.createElement("span");
        totalAmount.className = "crv-price";
        totalAmount.textContent = money(total);

        totalRow.append(totalLabel, totalAmount);
        popup.appendChild(totalRow);

        if (missing) {
            const note = document.createElement("div");
            note.className = "crv-missing";
            note.textContent =
                "Some prices unavailable; total is incomplete.";
            popup.appendChild(note);
        }

        // Explanatory hint removed to save screen space.
    }

    function updatePopup() {
        if (activeSection) {
            renderPopup();
        }
    }

    function openPopup(section) {
        if (!section || !section.isConnected) return;
        if (!getRewards(section).length) return;

        activeSection = section;
        renderPopup();
    }

    // ---------- Detect new success results ----------

    function inspectSection(section) {
        if (!section || !section.isConnected) return;

        const rewards = getRewards(section);
        if (!rewards.length) return;

        const key = signature(rewards);

        if (processed.get(section) === key) return;

        processed.set(section, key);
        openPopup(section);
    }

    function inspectNode(node) {
        if (!node || node.nodeType !== 1) return;

        if (node.matches && node.matches(RESULT_SELECTOR)) {
            inspectSection(node);
        }

        if (node.querySelectorAll) {
            node.querySelectorAll(RESULT_SELECTOR)
                .forEach(inspectSection);
        }
    }

    function scheduleInspect() {
        if (refreshScheduled) return;

        refreshScheduled = true;

        requestAnimationFrame(() => {
            refreshScheduled = false;

            document.querySelectorAll(RESULT_SELECTOR)
                .forEach(inspectSection);

            if (
                activeSection &&
                !activeSection.isConnected
            ) {
                closePopup();
            }
        });
    }

    // Observe crime-result changes, not popup contents.
    const observer = new MutationObserver(mutations => {
        let shouldInspect = false;

        for (const mutation of mutations) {
            const target = mutation.target.nodeType === 1
                ? mutation.target
                : mutation.target.parentElement;

            if (
                target &&
                target.closest &&
                target.closest("#" + POPUP_ID)
            ) {
                continue;
            }

            for (const node of mutation.addedNodes) {
                if (node.nodeType !== 1) continue;

                if (
                    (node.matches &&
                     node.matches(RESULT_SELECTOR)) ||
                    (node.querySelector &&
                     node.querySelector(RESULT_SELECTOR)) ||
                    (node.matches &&
                     node.matches(ITEM_SELECTOR)) ||
                    (node.querySelector &&
                     node.querySelector(ITEM_SELECTOR))
                ) {
                    inspectNode(node);
                    shouldInspect = true;
                }
            }

            if (mutation.removedNodes.length && activeSection) {
                shouldInspect = true;
            }
        }

        if (shouldInspect) {
            scheduleInspect();
        }
    });

    observer.observe(document.body, {
        childList: true,
        subtree: true
    });

    scheduleInspect();
    loadPrices();
})();

 // ==UserScript==
 // @name         Torn Final-Hit History
 // @namespace    tornpda-final-hit-history
 // @version      1.3.0
 // @description  Tracks live trophy-marked fight log entries locally.
 // @match        https://www.torn.com/*
 // @run-at       document-idle
 // @grant        none
 // ==/UserScript==

(function () {
    "use strict";

    const PREFIX = "[Final Hit History]";
    const STORAGE_KEY = "tornpda_final_hit_history_v1";
    const MAX_ENTRIES = 20;
    const BUTTON_ID = "torn-fhh-button";
    const PANEL_ID = "torn-fhh-panel";
    const STYLE_ID = "torn-fhh-style";
    const WAKE_BUTTON_ID = "torn-fhh-wake-button";

    if (window.__tornFinalHitHistoryInitialized) return;
    window.__tornFinalHitHistoryInitialized = true;

    let observer = null;
    let scanTimer = null;
    let panelOpen = false;
    let keepScreenOn = false;
    let screenWakeLock = null;
    let previousPage = location.href;
    let baselineEstablished = false;
    let previousEntries = new Map();
    let lastSaved = new Map();

    // ---------------------------------------------------------
    // PAGE DETECTION
    // ---------------------------------------------------------

    function isSupportedPage() {
        const url = new URL(location.href);
        const path = url.pathname.toLowerCase();
        const sid = (url.searchParams.get("sid") || "").toLowerCase();

        return (
            (path.endsWith("/page.php") && sid === "attack") ||
            path.endsWith("/profiles.php") ||
            path.endsWith("/profile.php")
        );
    }

    function getPageIdentity() {
        const url = new URL(location.href);
        return (
            url.searchParams.get("user2ID") ||
            url.searchParams.get("XID") ||
            url.searchParams.get("userID") ||
            ""
        );
    }

    // ---------------------------------------------------------
    // TIMESTAMP (TCT / UTC)
    // ---------------------------------------------------------

    function getTCTTimestamp() {
        const now = new Date();
        const date = new Intl.DateTimeFormat("en-CA", {
            timeZone: "UTC",
            year: "numeric",
            month: "2-digit",
            day: "2-digit"
        }).format(now);

        const time = new Intl.DateTimeFormat("en-GB", {
            timeZone: "UTC",
            hour: "2-digit",
            minute: "2-digit",
            second: "2-digit",
            hourCycle: "h23"
        }).format(now);

        return {
            iso: now.toISOString(),
            display: `${date} ${time} TCT`
        };
    }

    // ---------------------------------------------------------
    // LOCAL STORAGE
    // ---------------------------------------------------------

    function loadEntries() {
        try {
            const data = localStorage.getItem(STORAGE_KEY);
            const entries = data ? JSON.parse(data) : [];
            return Array.isArray(entries) ? entries : [];
        } catch (error) {
            console.error(PREFIX, "Unable to read history.", error);
            return [];
        }
    }

    function saveEntries(entries) {
        try {
            localStorage.setItem(
                STORAGE_KEY,
                JSON.stringify(entries.slice(0, MAX_ENTRIES))
            );
            return true;
        } catch (error) {
            console.error(PREFIX, "Unable to save history.", error);
            return false;
        }
    }

    function cleanText(value) {
        return String(value || "").replace(/\s+/g, " ").trim();
    }

    function getElementText(element) {
        return cleanText(element.innerText || element.textContent || "");
    }

    // ---------------------------------------------------------
    // TROPHY DETECTION
    // ---------------------------------------------------------

    function looksLikeTrophy(element) {
        const values = [
            element.getAttribute("alt"),
            element.getAttribute("title"),
            element.getAttribute("aria-label"),
            element.getAttribute("data-testid"),
            element.getAttribute("src"),
            element.getAttribute("class"),
            element.getAttribute("href")
        ];

        // Limit markup inspection to avoid processing huge containers.
        if (element.outerHTML) {
            values.push(element.outerHTML.slice(0, 700));
        }

        return /trophy|winner|winning|victory|final.?hit/i.test(
            values.filter(Boolean).join(" ")
        );
    }

    function findLogRow(icon) {
        let element = icon.parentElement;
        let fallback = null;

        for (let depth = 0; element && depth < 10; depth++) {
            const text = getElementText(element);

            // Ignore page-sized containers and very short labels.
            if (text.length >= 12 && text.length <= 450) {
                const tag = element.tagName.toLowerCase();
                const role = element.getAttribute("role") || "";
                const classes = typeof element.className === "string"
                    ? element.className
                    : "";

                if (
                    tag === "tr" ||
                    tag === "li" ||
                    tag === "article" ||
                    role === "row" ||
                    /action|event|log|history|battle|outcome/i.test(classes)
                ) {
                    return element;
                }

                // Keep the nearest plausible text container as a fallback.
                if (!fallback) fallback = element;
            }

            element = element.parentElement;
        }

        return fallback;
    }

    function getTrophyEntries() {
        const elements = document.querySelectorAll(
            "img, svg, [role='img'], [aria-label], [title], [data-testid]"
        );

        const byRow = new Map();

        for (const icon of elements) {
            if (!looksLikeTrophy(icon)) continue;

            const row = findLogRow(icon);
            if (!row) continue;

            const text = getElementText(row);
            if (text.length < 12 || text.length > 450) continue;

            // A row may contain multiple trophy-related elements.
            byRow.set(row, text);
        }

        return byRow;
    }

    // ---------------------------------------------------------
    // RECORDING
    // ---------------------------------------------------------

    function recordEntry(action, row) {
        const timestamp = getTCTTimestamp();
        const pageIdentity = getPageIdentity();
        const entries = loadEntries();

        // Suppress repeated mutations for the same action briefly.
        // Unlike the old version, an identical action can be recorded
        // again later if it genuinely happens again.
        const dedupeKey = `${pageIdentity}|${action}`;
        const lastTime = lastSaved.get(dedupeKey);

        if (lastTime && Date.now() - lastTime < 15000) {
            return false;
        }

        const entry = {
            key: `${timestamp.iso}|${pageIdentity}|${action}`,
            timestamp: timestamp.iso,
            timestampTCT: timestamp.display,
            action,
            pageIdentity,
            pageUrl: location.href
        };

        entries.unshift(entry);
        while (entries.length > MAX_ENTRIES) entries.pop();

        if (!saveEntries(entries)) return false;

        lastSaved.set(dedupeKey, Date.now());

        // Keep the duplicate cache bounded.
        if (lastSaved.size > 100) {
            const cutoff = Date.now() - 60000;
            for (const [key, time] of lastSaved) {
                if (time < cutoff) lastSaved.delete(key);
            }
        }

        console.info(PREFIX, "Recorded final hit:", action);

        if (panelOpen) renderPanel();
        return true;
    }

    // ---------------------------------------------------------
    // LIVE CHANGE DETECTION
    // ---------------------------------------------------------

    function resetBaseline() {
        baselineEstablished = false;
        previousEntries = new Map();
    }

    function scanFightLog() {
        if (!isSupportedPage()) return;

        if (previousPage !== location.href) {
            previousPage = location.href;
            resetBaseline();
        }

        const currentEntries = getTrophyEntries();

        // On initial load, remember what's already visible without
        // treating an old fight as a newly observed fight.
        if (!baselineEstablished) {
            if (currentEntries.size > 0) {
                previousEntries = new Map(currentEntries);
                baselineEstablished = true;
                console.info(
                    PREFIX,
                    "Baseline established with",
                    currentEntries.size,
                    "trophy row(s)."
                );
            }
            return;
        }

        // Compare row identity AND text. This catches an existing row
        // whose text changes without Torn creating a new DOM element.
        for (const [row, text] of currentEntries) {
            const oldText = previousEntries.get(row);

            if (oldText === undefined) {
                // A new row has appeared. If it duplicates a currently
                // visible row's text, don't record the same visible item twice.
                const alreadyVisible = Array.from(previousEntries.values())
                    .includes(text);

                if (!alreadyVisible) recordEntry(text, row);
            } else if (oldText !== text) {
                // Same trophy row, updated text.
                recordEntry(text, row);
            }
        }

        // If Torn replaces the entire log, row elements disappear.
        // Compare the new snapshot against the old text snapshot as well.
        const oldTexts = new Set(previousEntries.values());
        const newTexts = new Set(currentEntries.values());

        for (const text of newTexts) {
            if (!oldTexts.has(text)) {
                const alreadyHandled = Array.from(currentEntries.entries())
                    .some(([row, rowText]) =>
                        rowText === text && previousEntries.has(row)
                    );

                if (!alreadyHandled) recordEntry(text, null);
            }
        }

        previousEntries = new Map(currentEntries);
    }

    function scheduleScan() {
        if (scanTimer) clearTimeout(scanTimer);

        // Short debounce: lets Torn finish a batch of DOM changes,
        // while still responding quickly to a live fight update.
        scanTimer = setTimeout(() => {
            scanTimer = null;
            scanFightLog();
        }, 150);
    }

    function startObserver() {
        if (observer) observer.disconnect();
        if (!document.body) return;

        observer = new MutationObserver(scheduleScan);

        observer.observe(document.body, {
            childList: true,
            subtree: true,
            characterData: true,
            attributes: true,
            attributeFilter: [
                "src", "alt", "title", "aria-label",
                "class", "data-testid", "href"
            ]
        });
    }

    // ---------------------------------------------------------
    // SCREEN WAKE LOCK
    // ---------------------------------------------------------

    async function enableScreenWakeLock() {
        if (screenWakeLock) {
            keepScreenOn = true;
            updateWakeButton();
            return;
        }

        if (!isSupportedPage()) return;

        if (!navigator.wakeLock ||
            typeof navigator.wakeLock.request !== "function") {
            alert("Screen wake lock is not supported by this browser.");
            keepScreenOn = false;
            updateWakeButton();
            return;
        }

        try {
            const lock = await navigator.wakeLock.request("screen");
            screenWakeLock = lock;
            keepScreenOn = true;

            lock.addEventListener("release", () => {
                if (screenWakeLock === lock) screenWakeLock = null;
                updateWakeButton();
            });

            updateWakeButton();
            console.info(PREFIX, "Screen wake lock enabled.");
        } catch (error) {
            keepScreenOn = false;
            screenWakeLock = null;
            updateWakeButton();
            alert("Could not keep the screen awake. Check browser support.");
            console.warn(PREFIX, "Wake lock request failed:", error);
        }
    }

    async function disableScreenWakeLock() {
        keepScreenOn = false;
        const lock = screenWakeLock;
        screenWakeLock = null;

        if (lock) {
            try {
                await lock.release();
            } catch (error) {
                console.warn(PREFIX, "Wake lock release failed.", error);
            }
        }

        updateWakeButton();
    }

    function toggleScreenWakeLock() {
        if (keepScreenOn) disableScreenWakeLock();
        else enableScreenWakeLock();
    }

    function updateWakeButton() {
        const button = document.getElementById(WAKE_BUTTON_ID);
        if (!button) return;

        const active = keepScreenOn && screenWakeLock !== null;
        button.textContent = active
            ? "☀ Screen On: ON"
            : "☾ Screen On: OFF";
        button.style.background = active ? "#27632f" : "#303a42";
    }

    document.addEventListener("visibilitychange", () => {
        if (
            keepScreenOn &&
            isSupportedPage() &&
            document.visibilityState === "visible" &&
            !screenWakeLock
        ) {
            enableScreenWakeLock();
        }

        // A page becoming visible can also expose fight-log updates
        // that happened while the browser was backgrounded.
        scheduleScan();
    });

    window.addEventListener("pagehide", () => {
        keepScreenOn = false;

        if (screenWakeLock) {
            const lock = screenWakeLock;
            screenWakeLock = null;
            lock.release().catch(() => {});
        }
    });

    // ---------------------------------------------------------
    // STYLES
    // ---------------------------------------------------------

    function addStyles() {
        if (document.getElementById(STYLE_ID)) return;

        const style = document.createElement("style");
        style.id = STYLE_ID;
        style.textContent = `
            #${BUTTON_ID}, #${WAKE_BUTTON_ID} {
                position: fixed;
                right: 8px;
                z-index: 2147483000;
                border: 1px solid #8da8ba;
                border-radius: 8px;
                color: #fff;
                padding: 7px 9px;
                font: 600 12px/1.2 sans-serif;
                box-shadow: 0 2px 8px rgba(0,0,0,.55);
                cursor: pointer;
            }
            #${BUTTON_ID} {
                top: 8px;
                background: #17364a;
            }
            #${WAKE_BUTTON_ID} {
                top: 43px;
                background: #303a42;
            }
            #${PANEL_ID} {
                position: fixed;
                top: 78px;
                right: 8px;
                z-index: 2147483001;
                width: min(360px, calc(100vw - 16px));
                max-height: 65vh;
                overflow-y: auto;
                box-sizing: border-box;
                padding: 9px;
                border: 1px solid #6b8292;
                border-radius: 10px;
                background: #171a1d;
                color: #f5f5f5;
                box-shadow: 0 5px 18px rgba(0,0,0,.75);
                font: 12px/1.35 sans-serif;
            }
            #${PANEL_ID} * {
                box-sizing: border-box;
            }
            #${PANEL_ID} .fhh-header {
                display: flex;
                align-items: center;
                justify-content: space-between;
                gap: 8px;
                margin-bottom: 7px;
            }
            #${PANEL_ID} .fhh-title {
                font-size: 14px;
                font-weight: 700;
                color: #fff;
            }
            #${PANEL_ID} .fhh-button {
                border: 1px solid #738795;
                border-radius: 6px;
                padding: 5px 8px;
                background: #303a42;
                color: #fff;
                font: inherit;
                cursor: pointer;
            }
            #${PANEL_ID} .fhh-entry {
                padding: 7px 0;
                border-top: 1px solid #454b50;
                overflow-wrap: anywhere;
            }
            #${PANEL_ID} .fhh-time {
                margin-bottom: 3px;
                color: #8fdaff;
                font-weight: 700;
            }
            #${PANEL_ID} .fhh-action {
                color: #f5f5f5;
            }
            #${PANEL_ID} .fhh-empty,
            #${PANEL_ID} .fhh-footer {
                color: #c4cbd0;
                padding: 6px 0;
            }
        `;
        document.head.appendChild(style);
    }

    // ---------------------------------------------------------
    // BUTTONS
    // ---------------------------------------------------------

    function createButton() {
        if (!document.getElementById(BUTTON_ID)) {
            const button = document.createElement("button");
            button.id = BUTTON_ID;
            button.type = "button";
            button.textContent = "🏆 Fight History";

            button.addEventListener("click", () => {
                if (document.getElementById(PANEL_ID)) {
                    document.getElementById(PANEL_ID).remove();
                    panelOpen = false;
                } else {
                    panelOpen = true;
                    renderPanel();
                }
            });

            document.body.appendChild(button);
        }

        if (!document.getElementById(WAKE_BUTTON_ID)) {
            const wakeButton = document.createElement("button");
            wakeButton.id = WAKE_BUTTON_ID;
            wakeButton.type = "button";
            wakeButton.addEventListener("click", toggleScreenWakeLock);
            document.body.appendChild(wakeButton);
        }

        updateWakeButton();
    }

    // ---------------------------------------------------------
    // HISTORY POPUP
    // ---------------------------------------------------------

    function renderPanel() {
        document.getElementById(PANEL_ID)?.remove();

        const panel = document.createElement("div");
        panel.id = PANEL_ID;

        const header = document.createElement("div");
        header.className = "fhh-header";

        const title = document.createElement("div");
        title.className = "fhh-title";
        title.textContent = "🏆 Final-Hit History";

        const controls = document.createElement("div");

        const clearButton = document.createElement("button");
        clearButton.className = "fhh-button";
        clearButton.textContent = "Clear";
        clearButton.addEventListener("click", () => {
            if (!confirm("Clear all stored fight records?")) return;

            localStorage.removeItem(STORAGE_KEY);
            lastSaved.clear();
            renderPanel();
        });

        const closeButton = document.createElement("button");
        closeButton.className = "fhh-button";
        closeButton.textContent = "✕";
        closeButton.setAttribute("aria-label", "Close history");

        closeButton.addEventListener("click", () => {
            panel.remove();
            panelOpen = false;
        });

        controls.append(clearButton, closeButton);
        header.append(title, controls);
        panel.appendChild(header);

        const entries = loadEntries();

        if (!entries.length) {
            const empty = document.createElement("div");
            empty.className = "fhh-empty";
            empty.textContent =
                "No final hits recorded yet. Keep this page open while a fight log updates.";
            panel.appendChild(empty);
        } else {
            for (const entry of entries) {
                const card = document.createElement("div");
                card.className = "fhh-entry";

                const time = document.createElement("div");
                time.className = "fhh-time";
                time.textContent =
                    entry.timestampTCT || "Timestamp unavailable";

                const action = document.createElement("div");
                action.className = "fhh-action";
                action.textContent = entry.action || "Entry unavailable";

                card.append(time, action);
                panel.appendChild(card);
            }
        }

        const footer = document.createElement("div");
        footer.className = "fhh-footer";
        footer.textContent =
            `${entries.length}/${MAX_ENTRIES} records · Stored locally · No API calls`;
        panel.appendChild(footer);

        document.body.appendChild(panel);
    }

    // ---------------------------------------------------------
    // PAGE NAVIGATION
    // ---------------------------------------------------------

    function checkPageChange() {
        if (location.href === previousPage) return;

        previousPage = location.href;
        resetBaseline();

        if (!isSupportedPage()) {
            keepScreenOn = false;

            if (screenWakeLock) {
                const lock = screenWakeLock;
                screenWakeLock = null;
                lock.release().catch(() => {});
            }

            document.getElementById(BUTTON_ID)?.remove();
            document.getElementById(WAKE_BUTTON_ID)?.remove();
            document.getElementById(PANEL_ID)?.remove();
            panelOpen = false;
            return;
        }

        addStyles();
        createButton();
        scanFightLog();
    }

    // ---------------------------------------------------------
    // INITIALIZATION
    // ---------------------------------------------------------

    function init() {
        if (!isSupportedPage()) return;

        addStyles();
        createButton();
        startObserver();

        // Keep checking as well as observing mutations. This catches
        // some updates that don't produce a useful DOM mutation.
        scanFightLog();
        setInterval(() => {
            checkPageChange();
            if (isSupportedPage()) scanFightLog();
        }, 1000);

        console.info(PREFIX, "Live fight-log observer started.");
    }

    if (document.body) {
        init();
    } else {
        document.addEventListener("DOMContentLoaded", init, { once: true });
    }
})();

// ==UserScript==
// @name         Torn City Store Market RRP Highlighter
// @namespace    tornpda-store-rrp-highlighter
// @version      7.0.0
// @description  Displays cached Torn API market values below city resale prices.
// @match        https://www.torn.com/*
// @run-at       document-end
// @grant        none
// ==/UserScript==

(function () {
    "use strict";

    // Prevent duplicate initialization on the same page.
    if (window.__storeRRPv7Running) return;
    window.__storeRRPv7Running = true;

    const PREFIX = "[Store RRP]";

    // TornPDA should replace this placeholder with your configured API key.
    const API_KEY = "###PDA-APIKEY###";

    const API_URL =
        "https://api.torn.com/torn/?selections=items&key=";

    const CACHE_KEY = "store_rrp_market_value_v7";
    const RETRY_KEY = "store_rrp_market_value_v7_retry";
    const CACHE_TTL = 7 * 24 * 60 * 60 * 1000;
    const RETRY_COOLDOWN = 15 * 60 * 1000;

    const ROW_SELECTOR =
        ".sell-list-wrap ul.sell-items-list > li";

    const LABEL_CLASS = "store-rrp-market-value";

    let prices = {};
    let activeList = null;
    let listObserver = null;
    let pageObserver = null;
    let scanTimer = null;
    let initialized = false;
    let pricesLoaded = false;

    function log(...args) {
        console.log(PREFIX, ...args);
    }

    function normalizeName(name) {
        return String(name || "")
            .trim()
            .toLowerCase()
            .replace(/\s+/g, " ");
    }

    function formatMoney(value) {
        return "$" + Math.round(value).toLocaleString("en-US");
    }

    function validPrices(value) {
        if (!value || typeof value !== "object") return false;

        return Object.entries(value).some(function ([name, price]) {
            return name.length > 0 &&
                Number.isFinite(price) &&
                price >= 0;
        });
    }

    function readCache() {
        try {
            const raw = localStorage.getItem(CACHE_KEY);
            if (!raw) return null;

            const cache = JSON.parse(raw);

            if (
                !cache ||
                typeof cache.savedAt !== "number" ||
                cache.savedAt > Date.now() ||
                !validPrices(cache.prices)
            ) {
                return null;
            }

            return cache;
        } catch (error) {
            log("Cache read failed:", error.message);
            return null;
        }
    }

    function saveCache(newPrices) {
        try {
            localStorage.setItem(
                CACHE_KEY,
                JSON.stringify({
                    savedAt: Date.now(),
                    prices: newPrices
                })
            );
        } catch (error) {
            log("Cache save failed:", error.message);
        }
    }

    function isCacheFresh(cache) {
        return !!cache &&
            Date.now() - cache.savedAt < CACHE_TTL;
    }

    function retryIsCoolingDown() {
        try {
            const retryAt = Number(
                localStorage.getItem(RETRY_KEY) || 0
            );

            return retryAt > Date.now();
        } catch (_) {
            return false;
        }
    }

    function setRetryCooldown() {
        try {
            localStorage.setItem(
                RETRY_KEY,
                String(Date.now() + RETRY_COOLDOWN)
            );
        } catch (_) {
            // The cooldown still applies to this run.
        }
    }

    function clearRetryCooldown() {
        try {
            localStorage.removeItem(RETRY_KEY);
        } catch (_) {
            // Non-fatal.
        }
    }

    async function fetchPrices() {
        if (
            !API_KEY ||
            API_KEY.includes("###") ||
            API_KEY.length < 10
        ) {
            throw new Error(
                "TornPDA did not inject a valid API key. " +
                "Check TornPDA's API-key settings."
            );
        }

        if (typeof PDA_httpGet !== "function") {
            throw new Error(
                "PDA_httpGet is unavailable. " +
                "Check that TornPDA is running this script."
            );
        }

        const response = await PDA_httpGet(
            API_URL + encodeURIComponent(API_KEY),
            {}
        );

        if (
            !response ||
            typeof response.responseText !== "string"
        ) {
            throw new Error("No readable response from the Torn API.");
        }

        let data;

        try {
            data = JSON.parse(response.responseText);
        } catch (_) {
            throw new Error("The Torn API response was not valid JSON.");
        }

        if (data.error) {
            throw new Error(
                "Torn API error " + data.error.code +
                ": " + data.error.error
            );
        }

        if (!data.items || typeof data.items !== "object") {
            throw new Error("The API response contained no item dataset.");
        }

        const result = {};

        for (const item of Object.values(data.items)) {
            if (!item || typeof item.name !== "string") continue;

            const name = normalizeName(item.name);
            const value = Number(item.market_value);

            if (
                name &&
                item.market_value !== null &&
                item.market_value !== undefined &&
                Number.isFinite(value) &&
                value >= 0
            ) {
                result[name] = value;
            }
        }

        if (!validPrices(result)) {
            throw new Error(
                "No valid market_value prices were found."
            );
        }

        saveCache(result);
        clearRetryCooldown();

        log("Successfully refreshed market values:", Object.keys(result).length);

        return result;
    }

    async function loadPrices() {
        const cache = readCache();

        // Reuse fresh prices without making an API request.
        if (isCacheFresh(cache)) {
            prices = cache.prices;
            log("Using cached market values.");
            return;
        }

        // Avoid repeated API attempts after a recent failure.
        if (retryIsCoolingDown()) {
            if (cache) {
                prices = cache.prices;
                log("API retry cooldown active; using cached prices.");
            } else {
                log("API retry cooldown active; no cached prices available.");
            }
            return;
        }

        try {
            prices = await fetchPrices();
        } catch (error) {
            setRetryCooldown();

            if (cache) {
                prices = cache.prices;
                log(
                    "Refresh failed; using cached prices:",
                    error.message
                );
            } else {
                prices = {};
                log("Could not load market prices:", error.message);
            }
        }
    }

    function scanRows() {
    if (!activeList || !activeList.isConnected) return;

    const rows = activeList.querySelectorAll(":scope > li");
    let displayed = 0;

    for (const row of rows) {
        const item = row.querySelector("ul.item");
        if (!item) continue;

        const nameNode = item.querySelector(".name");
        const cityPrice = item.querySelector("li.value");

        if (!nameNode || !cityPrice) continue;

        const name = normalizeName(nameNode.textContent);
        if (!name) continue;

        let label = cityPrice.querySelector("." + LABEL_CLASS);

        if (label && label.dataset.itemName !== name) {
            label.remove();
            label = null;
        }

        const marketValue = prices[name];

        if (!Number.isFinite(marketValue)) {
            if (label) label.remove();
            continue;
        }

        // Read the city's fixed resale price, excluding our own label.
        const cityPriceText = Array.from(cityPrice.childNodes)
            .filter(node =>
                !(node.nodeType === 1 &&
                  node.classList.contains(LABEL_CLASS))
            )
            .map(node => node.textContent)
            .join(" ");

        const cityValue = Number(
            cityPriceText.replace(/[^0-9.]/g, "")
        );

        if (!label) {
            label = document.createElement("div");
            label.className = LABEL_CLASS;
            label.dataset.itemName = name;

            label.style.cssText =
                "display:block;" +
                "margin-top:3px;" +
                "font-size:10px;" +
                "font-weight:600;" +
                "line-height:1.3;";

            cityPrice.appendChild(label);
        }

        label.textContent =
            "Market RRP: " + formatMoney(marketValue);

        label.style.color =
            Number.isFinite(cityValue) && marketValue < cityValue
                ? "#32cd32"
                : "#4da6ff";

        displayed++;
    }

    log(
        "Scan complete. Rows:",
        rows.length,
        "Prices displayed:",
        displayed
    );
}

    function scheduleScan() {
        if (scanTimer !== null) clearTimeout(scanTimer);

        scanTimer = setTimeout(function () {
            scanTimer = null;
            scanRows();
        }, 200);
    }

    function bindList(list) {
        if (list === activeList) return;

        if (listObserver) {
            listObserver.disconnect();
            listObserver = null;
        }

        activeList = list;

        if (!list) return;

        if (pricesLoaded) scanRows();

        listObserver = new MutationObserver(function (records) {
            const relevant = records.some(function (record) {
                const target = record.target.nodeType === 1
                    ? record.target
                    : record.target.parentElement;

                // Ignore text or child changes inside our own labels.
                if (
                    target &&
                    target.closest &&
                    target.closest("." + LABEL_CLASS)
                ) {
                    return false;
                }

                const changedNodes = [
                    ...record.addedNodes,
                    ...record.removedNodes
                ];

                return changedNodes.some(function (node) {
                    if (node.nodeType !== 1) return false;

                    if (
                        node.classList &&
                        node.classList.contains(LABEL_CLASS)
                    ) {
                        return false;
                    }

                    return true;
                }) || record.type === "characterData";
            });

            if (relevant) scheduleScan();
        });

        listObserver.observe(list, {
            childList: true,
            subtree: true,
            characterData: true
        });

        log("Watching the Sell Items list.");
    }

    function checkForList() {
        const list = document.querySelector(
            ".sell-list-wrap ul.sell-items-list"
        );

        if (!list) return;

        bindList(list);

        if (!initialized) {
            initialized = true;
            log("Sell Items list found; loading prices.");

            loadPrices().then(function () {
                pricesLoaded = true;

                const currentList = document.querySelector(
                    ".sell-list-wrap ul.sell-items-list"
                );

                if (currentList) bindList(currentList);

                scanRows();
            });
        }
    }

    function start() {
        // No API request is made until the target list exists.
        checkForList();

        // Handle Torn pages that populate or replace the list later.
        pageObserver = new MutationObserver(function () {
            checkForList();
        });

        pageObserver.observe(document.body, {
            childList: true,
            subtree: true
        });
    }

    if (document.body) {
        start();
    } else {
        document.addEventListener("DOMContentLoaded", start, {
            once: true
        });
    }
})();

// ==UserScript==
// @name         TornPDA - City Sell Price
// @namespace    tornpda-city-sell-price
// @version      4.1.1
// @description  Displays the city sell price beside items on the Item Market.
// @author       OpenAI
// @match        https://www.torn.com/page.php?sid=ItemMarket*
// @run-at       document-end
// ==/UserScript==

(function () {
'use strict';

const API_KEY =
    '###PDA-APIKEY###';

const API_BASE =
    'https://api.torn.com/v2/';

const CACHE_KEY =
    'tornpda_city_prices_v4';

const CACHE_TIME =
    24 * 60 * 60 * 1000;

const TILE_SELECTOR =
    '[class*="itemTile___"]';

let itemData = {};
let running = false;

function money(value) {
    return '$' +
        Math.round(value)
            .toLocaleString('en-US');
}

function getNumber(value) {
    if (
        value === null ||
        value === undefined
    ) {
        return null;
    }

    const n = Number(
        String(value)
            .replace(/[$,]/g, '')
            .replace(/[^\d.-]/g, '')
    );

    return Number.isFinite(n)
        ? n
        : null;
}

async function apiGet(url) {
    if (
        typeof window.PDA_httpGet ===
        'function'
    ) {
        const response =
            await window.PDA_httpGet(
                url,
                {
                    Accept: 'application/json'
                }
            );

        if (
            response.status &&
            response.status >= 400
        ) {
            throw new Error(
                'HTTP ' + response.status
            );
        }

        return JSON.parse(
            response.responseText
        );
    }

    const response = await fetch(url);

    if (!response.ok) {
        throw new Error(
            'HTTP ' + response.status
        );
    }

    return response.json();
}

async function loadItems() {
    const cached =
        localStorage.getItem(CACHE_KEY);

    if (cached) {
        try {
            const saved = JSON.parse(cached);

            if (
                saved.time &&
                saved.items &&
                Date.now() - saved.time <
                    CACHE_TIME
            ) {
                itemData = saved.items;
                return;
            }
        } catch (e) {}
    }

    const url =
        API_BASE +
        'torn/items?key=' +
        encodeURIComponent(API_KEY);

    const data = await apiGet(url);

    if (data.error) {
        throw new Error(
            data.error.error ||
            'Torn API error'
        );
    }

    const source =
        Array.isArray(data.items)
            ? data.items
            : Object.values(data.items || {});

    const database = {};

    source.forEach(item => {
        if (!item || !item.id) {
            return;
        }

        const cityPrice = getCityPrice(item);

        if (
            cityPrice !== null &&
            cityPrice > 0
        ) {
            database[String(item.id)] = {
                name: item.name || '',
                cityPrice
            };
        }
    });

    itemData = database;

    localStorage.setItem(
        CACHE_KEY,
        JSON.stringify({
            time: Date.now(),
            items: database
        })
    );
}

function getCityPrice(item) {
    const shops =
        item.value &&
        Array.isArray(item.value.shops)
            ? item.value.shops
            : Array.isArray(item.shops)
                ? item.shops
                : [];

    for (const shop of shops) {
        const shopText =
            JSON.stringify(shop).toLowerCase();

        if (!shopText.includes('city')) {
            continue;
        }

        const possiblePrices = [
            shop.sell_price,
            shop.sellPrice,
            shop.price,
            shop.value,
            shop.sell
        ];

        for (const value of possiblePrices) {
            const price = getNumber(value);

            if (price !== null && price > 0) {
                return price;
            }
        }
    }

    const oldPrice = getNumber(item.sell_price);

    if (oldPrice !== null && oldPrice > 0) {
        return oldPrice;
    }

    if (item.value) {
        const possiblePrices = [
            item.value.sell_price,
            item.value.sellPrice
        ];

        for (const value of possiblePrices) {
            const price = getNumber(value);

            if (price !== null && price > 0) {
                return price;
            }
        }
    }

    return null;
}

function getTiles() {
    return Array.from(
        document.querySelectorAll(TILE_SELECTOR)
    );
}

function getItemId(tile) {
    const images = tile.querySelectorAll('img');

    for (const img of images) {
        const sources = [
            img.src,
            img.getAttribute('src'),
            img.getAttribute('data-src')
        ];

        for (const source of sources) {
            if (!source) {
                continue;
            }

            const match =
                source.match(/items\/(\d+)/);

            if (match) {
                return match[1];
            }
        }
    }

    const elements = tile.querySelectorAll('*');

    for (const element of elements) {
        for (
            const attribute of
            Array.from(element.attributes || [])
        ) {
            if (
                /item.*id/i.test(attribute.name) &&
                /^\d+$/.test(attribute.value)
            ) {
                return attribute.value;
            }
        }
    }

    return null;
}

/*
 * Finds a visible dollar price on the item tile.
 * Avoids reading the CITY label inserted by this script.
 */
function getDisplayedMarketPrice(tile) {
    const priceSelectors = [
        '[class*="price"]',
        '[class*="Price"]',
        '[class*="cost"]',
        '[class*="Cost"]'
    ];

    for (const selector of priceSelectors) {
        const nodes = tile.querySelectorAll(selector);

        for (const node of nodes) {
            if (
                node.closest('.pda-city-price') ||
                node.querySelector('.pda-city-price')
            ) {
                continue;
            }

            const text =
                (node.innerText || node.textContent || '')
                    .trim();

            if (!text || !text.includes('$')) {
                continue;
            }

            const match =
                text.match(/\$\s*[\d,]+(?:\.\d+)?/);

            if (match) {
                const price = getNumber(match[0]);

                if (price !== null && price > 0) {
                    return price;
                }
            }
        }
    }

    return null;
}

function addCityPrice(tile, price) {
    const old =
        tile.querySelector('.pda-city-price');

    if (old) {
        old.remove();
    }

    const marketPrice =
        getDisplayedMarketPrice(tile);

    const label =
        document.createElement('div');

    label.className = 'pda-city-price';

    label.textContent =
        'CITY ' + money(price);

    // Blue when city sell price is LOWER
    // than the market listing price.
    if (
        marketPrice !== null &&
        price < marketPrice
    ) {
        label.classList.add('pda-city-blue');
    } else {
        label.classList.add('pda-city-green');
    }

    tile.appendChild(label);
}

function removeCityPrice(tile) {
    const old =
        tile.querySelector('.pda-city-price');

    if (old) {
        old.remove();
    }
}

function updateVisibleItems() {
    if (running) {
        return;
    }

    running = true;

    try {
        const tiles = getTiles();

        tiles.forEach(tile => {
            const id = getItemId(tile);

            if (!id) {
                removeCityPrice(tile);
                return;
            }

            const data = itemData[String(id)];

            if (!data || !data.cityPrice) {
                removeCityPrice(tile);
                return;
            }

            addCityPrice(tile, data.cityPrice);
        });
    } finally {
        running = false;
    }
}

function addStyles() {
    if (
        document.getElementById(
            'pda-city-price-style'
        )
    ) {
        return;
    }

    const style = document.createElement('style');

    style.id = 'pda-city-price-style';

    style.textContent = `
        .pda-city-price {
            display: inline-block;
            box-sizing: border-box;
            margin: 2px 0 1px 4px;
            padding: 1px 3px;
            border-radius: 3px;
            background: #263238;
            border: 1px solid currentColor;
            font-size: 9px;
            font-weight: 700;
            line-height: 1.2;
            white-space: nowrap;
            position: relative;
            z-index: 100;
        }

        .pda-city-price.pda-city-green {
            color: #7CFF8B;
        }

        .pda-city-price.pda-city-blue {
            color: #4DA6FF;
        }
    `;

    document.head.appendChild(style);
}

async function initialize() {
    addStyles();

    let attempts = 0;

    while (
        !document.querySelector('#item-market-root') &&
        attempts < 40
    ) {
        await new Promise(resolve =>
            setTimeout(resolve, 250)
        );

        attempts++;
    }

    if (
        !document.querySelector('#item-market-root')
    ) {
        return;
    }

    try {
        await loadItems();
        updateVisibleItems();
    } catch (error) {
        console.error('[City Sell Price]', error);
    }

    const root =
        document.querySelector('#item-market-root');

    if (!root) {
        return;
    }

    let timer = null;

    const observer = new MutationObserver(() => {
        clearTimeout(timer);

        timer = setTimeout(() => {
            updateVisibleItems();
        }, 150);
    });

    observer.observe(root, {
        childList: true,
        subtree: true
    });
}

initialize();

})();

// ==UserScript==
// @name         TornPDA Drug Trade Route Optimizer
// @namespace    tornpda-drug-trade-route-optimizer
// @version      1.4.0
// @description  Drug price comparisons and optimized travel trade routes.
// @match        https://www.torn.com/page.php*
// @grant        GM_xmlhttpRequest
// @connect      yata.yt
// @connect      api.prombot.co.uk
// @run-at       document-idle
// ==/UserScript==

(function () {
    "use strict";

    const PREFIX = "[Drug Route Optimizer]";
    const CACHE_KEY = "tornpda_drug_route_optimizer_v1";
    const QUANTITY_KEY = "tornpda_drug_route_quantity_v1";
    const CACHE_TTL = 15 * 60 * 1000;
    const STALE_TTL = 30 * 60 * 1000;

    const YATA_URL = "https://yata.yt/api/v1/travel/export/";
    const PROM_URL = "https://api.prombot.co.uk/api/travel";
    const PANEL_ID = "tdro-panel-v140";

    const COUNTRIES = [
        { code: "mex", name: "Mexico", minutes: 17 },
        { code: "cay", name: "Cayman Islands", minutes: 23 },
        { code: "can", name: "Canada", minutes: 27 },
        { code: "haw", name: "Hawaii", minutes: 89 },
        { code: "uni", name: "United Kingdom", minutes: 106 },
        { code: "arg", name: "Argentina", minutes: 111 },
        { code: "swi", name: "Switzerland", minutes: 116 },
        { code: "jap", name: "Japan", minutes: 149 },
        { code: "chi", name: "China", minutes: 160 },
        { code: "uae", name: "United Arab Emirates", minutes: 180 },
        { code: "sou", name: "South Africa", minutes: 197 }
    ];

    const DRUG_NAMES = [
        "Cannabis", "Weed", "Ecstasy", "Ketamine", "LSD",
        "Opium", "PCP", "Shrooms", "Speed", "Vicodin", "Xanax"
    ];

    const DRUG_ALIASES = Object.fromEntries(
        DRUG_NAMES.map(name => [normalizeKey(name), name])
    );

    let panel = null;
    let allItems = {};
    let routes = [];
    let countryRankings = {};
    let selectedCountry = null;
    let lastRefresh = 0;
    let loading = false;
    let errorMessage = "";
    let observer = null;
    let destinationCheckTimer = null;

    function normalizeKey(value) {
        return String(value ?? "").toLowerCase().replace(/[^a-z0-9]/g, "");
    }

    function log(...args) {
        console.log(PREFIX, ...args);
    }

    function escapeHtml(value) {
        return String(value ?? "").replace(/[&<>"']/g, char => ({
            "&": "&amp;", "<": "&lt;", ">": "&gt;",
            '"': "&quot;", "'": "&#39;"
        })[char]);
    }

    function money(value) {
        if (!Number.isFinite(Number(value))) return "N/A";
        return "$" + Math.round(Number(value)).toLocaleString("en-US");
    }

    function ordinal(number) {
        const n = Math.abs(number);
        const lastTwo = n % 100;
        if (lastTwo >= 11 && lastTwo <= 13) return number + "th";
        return number + (
            n % 10 === 1 ? "st" :
            n % 10 === 2 ? "nd" :
            n % 10 === 3 ? "rd" : "th"
        );
    }

    function canonicalDrug(name) {
        return DRUG_ALIASES[normalizeKey(name)] || null;
    }

    function getCountry(code) {
        return COUNTRIES.find(country => country.code === code) || null;
    }

    function isTravelScreen() {
        if (!location.href.includes("torn.com/page.php")) return false;
        const params = new URLSearchParams(location.search);
        return ["travelagency", "travel"].includes(params.get("sid"));
    }

    function getSavedQuantity() {
        try {
            const saved = Number(localStorage.getItem(QUANTITY_KEY));
            return Number.isFinite(saved) && saved >= 1
                ? Math.min(10000, Math.floor(saved))
                : 1;
        } catch (_) {
            return 1;
        }
    }

    function saveQuantity(value) {
        const quantity = Math.max(1, Math.min(10000, Math.floor(Number(value) || 1)));
        try {
            localStorage.setItem(QUANTITY_KEY, String(quantity));
        } catch (error) {
            log("Could not save quantity.", error);
        }
        return quantity;
    }

    function requestJson(url) {
        return new Promise((resolve, reject) => {
            if (typeof GM_xmlhttpRequest !== "function") {
                reject(new Error("TornPDA GM_xmlhttpRequest is unavailable."));
                return;
            }

            GM_xmlhttpRequest({
                method: "GET",
                url,
                timeout: 15000,
                headers: { Accept: "application/json" },
                onload: response => {
                    if (response.status < 200 || response.status >= 300) {
                        reject(new Error("HTTP " + response.status));
                        return;
                    }
                    try {
                        resolve(JSON.parse(response.responseText));
                    } catch (_) {
                        reject(new Error("Invalid JSON received."));
                    }
                },
                onerror: () => reject(new Error("Network request failed.")),
                ontimeout: () => reject(new Error("Request timed out."))
            });
        });
    }

    function readCache() {
        try {
            const cached = JSON.parse(localStorage.getItem(CACHE_KEY) || "null");
            return cached && typeof cached === "object" ? cached : null;
        } catch (_) {
            return null;
        }
    }

    function writeCache(yata, prom) {
        try {
            localStorage.setItem(CACHE_KEY, JSON.stringify({
                timestamp: Date.now(),
                yata,
                prom
            }));
        } catch (error) {
            log("Could not save price cache.", error);
        }
    }

    function findCountryBlock(data, code) {
        if (!data || typeof data !== "object") return null;

        for (const container of [
            data.stocks, data.countries, data.travel, data.data, data
        ]) {
            if (!container || typeof container !== "object") continue;
            const key = Object.keys(container).find(
                candidate => candidate.toLowerCase() === code
            );
            if (key) return container[key];
        }
        return null;
    }

    function extractItemArray(block) {
        if (Array.isArray(block)) return block;
        if (!block || typeof block !== "object") return [];

        for (const key of ["stocks", "items", "drugs", "stock", "data"]) {
            if (Array.isArray(block[key])) return block[key];
        }
        return [];
    }

    function parseFeed(data, sourceName) {
        const result = {};

        for (const country of COUNTRIES) {
            const block = findCountryBlock(data, country.code);
            result[country.code] = {};

            for (const item of extractItemArray(block)) {
                if (!item || typeof item !== "object") continue;

                const drugName = canonicalDrug(
                    item.name || item.item || item.drug || item.item_name
                );
                if (!drugName) continue;

                const cost = Number(
                    item.cost ?? item.price ?? item.buy_price ??
                    item.market_price ?? item.value
                );
                if (!Number.isFinite(cost) || cost <= 0) continue;

                const quantity = Number(
                    item.quantity ?? item.qty ?? item.stock ?? item.amount ?? 0
                );

                result[country.code][normalizeKey(drugName)] = {
                    id: String(item.id ?? item.item_id ?? normalizeKey(drugName)),
                    name: drugName,
                    cost,
                    quantity: Number.isFinite(quantity) ? quantity : 0,
                    source: sourceName
                };
            }
        }
        return result;
    }

    function buildCombinedItems(yataData, promData) {
        const yata = parseFeed(yataData, "YATA");
        const prom = parseFeed(promData, "Prometheus");
        const merged = {};

        for (const country of COUNTRIES) {
            merged[country.code] = {};
            for (const drugName of DRUG_NAMES) {
                const key = normalizeKey(drugName);
                // Prefer YATA when both feeds contain the same drug.
                const item = yata[country.code]?.[key] || prom[country.code]?.[key];
                if (item) merged[country.code][key] = { ...item, name: drugName };
            }
        }
        return merged;
    }

    function getDrugItem(countryCode, drugName) {
        return allItems?.[countryCode]?.[normalizeKey(drugName)] || null;
    }

    function getBuyPrice(countryCode, drugName) {
        const item = getDrugItem(countryCode, drugName);
        return item && item.cost > 0 ? item.cost : null;
    }

    // Estimated payout: 75% of the foreign shop's listed price.
    function getSellPrice(countryCode, drugName) {
        const buy = getBuyPrice(countryCode, drugName);
        return buy === null ? null : buy * 0.75;
    }
    function getCheapestBuy(drugName) {
        return COUNTRIES.map(country => ({
            country,
            price: getBuyPrice(country.code, drugName)
        }))
        .filter(entry => entry.price !== null)
        .sort((a, b) => a.price - b.price)[0] || null;
    }

    function getBestSell(drugName) {
        return COUNTRIES.map(country => ({
            country,
            price: getSellPrice(country.code, drugName)
        }))
        .filter(entry => entry.price !== null)
        .sort((a, b) => b.price - a.price)[0] || null;
    }

    function buildCountryRankings() {
        const result = {};

        for (const country of COUNTRIES) {
            const entries = DRUG_NAMES.map(name => {
                const buy = getBuyPrice(country.code, name);
                const sell = getSellPrice(country.code, name);
                if (buy === null || sell === null) return null;

                const bestBuy = getCheapestBuy(name);
                const bestSell = getBestSell(name);

                return {
                    name,
                    buy,
                    sell,
                    bestBuy,
                    bestSell,
                    buyDifference: bestBuy ? Math.max(0, buy - bestBuy.price) : null,
                    sellDifference: bestSell ? Math.max(0, bestSell.price - sell) : null
                };
            }).filter(Boolean);

            entries.sort((a, b) => b.sell - a.sell || a.name.localeCompare(b.name));

            result[country.code] = entries.map((entry, index) => ({
                ...entry,
                rank: index + 1
            }));
        }

        return result;
    }

    function getQuantity() {
        const input = panel?.querySelector("#tdro-quantity");
        return saveQuantity(input?.value ?? getSavedQuantity());
    }

    function buildRoutes() {
        const result = [];
        const requestedQuantity = getQuantity();

        for (const origin of COUNTRIES) {
            for (const destination of COUNTRIES) {
                if (origin.code === destination.code) continue;

                for (const drugName of DRUG_NAMES) {
                    const originItem = getDrugItem(origin.code, drugName);
                    const destinationItem = getDrugItem(destination.code, drugName);
                    if (!originItem || !destinationItem) continue;

                    const buyPrice = originItem.cost;
                    const sellPrice = destinationItem.cost * 0.75;
                    const profitPerUnit = sellPrice - buyPrice;
                    if (!Number.isFinite(profitPerUnit) || profitPerUnit <= 0) continue;

                    const quantityAvailable = originItem.quantity > 0
                        ? originItem.quantity
                        : requestedQuantity;
                    const quantity = Math.max(
                        1, Math.min(requestedQuantity, quantityAvailable)
                    );

                    const profit = profitPerUnit * quantity;
                    const minutes = origin.minutes * 2 + destination.minutes * 2 + 0.5;
                    const hourlyProfit = profit / (minutes / 60);
                    const cheapest = getCheapestBuy(drugName);

                    result.push({
                        drug: drugName,
                        origin,
                        destination,
                        buyPrice,
                        sellPrice,
                        quantity,
                        profitPerUnit,
                        profit,
                        minutes,
                        hourlyProfit,
                        buyStatus: !cheapest ? "unknown" :
                            originItem.cost <= cheapest.price ? "best" : "cheaper"
                    });
                }
            }
        }

        return result.sort((a, b) =>
            b.hourlyProfit - a.hourlyProfit || b.profit - a.profit
        );
    }

    function countryFromText(value) {
        const text = normalizeKey(value);
        if (!text) return null;

        const matches = COUNTRIES.filter(country =>
            text.includes(normalizeKey(country.name)) ||
            text === normalizeKey(country.code)
        );

        // Prefer full country names over short codes to avoid accidental matches.
        matches.sort((a, b) =>
            normalizeKey(b.name).length - normalizeKey(a.name).length
        );
        return matches[0]?.code || null;
    }

    function detectSelectedCountry() {
        const selectors = [
            '[class*="worldMap"] [aria-pressed="true"]',
            '[class*="worldMap"] [aria-selected="true"]',
            '[class*="worldMap"] [data-selected="true"]',
            '[class*="worldMap"] [class*="selected"]',
            'button[class*="destDropdownToggler"]',
            '[class*="destDropdownToggler"]'
        ];

        for (const selector of selectors) {
            for (const element of document.querySelectorAll(selector)) {
                const candidate = [
                    element.getAttribute("aria-label"),
                    element.getAttribute("title"),
                    element.getAttribute("data-country"),
                    element.getAttribute("data-destination"),
                    element.textContent
                ].filter(Boolean).join(" ");

                const code = countryFromText(candidate);
                if (code) return code;
            }
        }

        // Some versions of the travel map put the country name in a
        // selected image's alt text or in the accessible label of its parent.
        for (const element of document.querySelectorAll(
            '[class*="worldMap"] [aria-label], [class*="worldMap"] img[alt]'
        )) {
            const isSelected =
                element.getAttribute("aria-pressed") === "true" ||
                element.getAttribute("aria-selected") === "true" ||
                element.getAttribute("data-selected") === "true" ||
                /selected|active/i.test(element.className?.baseVal || element.className || "");

            if (!isSelected) continue;

            const code = countryFromText(
                element.getAttribute("aria-label") ||
                element.getAttribute("alt") ||
                element.getAttribute("title")
            );
            if (code) return code;
        }

        return null;
    }

    function updateSelectedCountry() {
        const detected = detectSelectedCountry();
        if (!detected || detected === selectedCountry) return false;

        selectedCountry = detected;
        routes = buildRoutes();
        render();
        log("Selected destination changed to", getCountry(detected)?.name || detected);
        return true;
    }

    function getDataStatus() {
        if (loading) return "Refreshing price feeds…";
        if (errorMessage) return errorMessage;
        if (!Object.values(allItems).some(items => Object.keys(items || {}).length)) {
            return "No price data loaded.";
        }
        return "Selling prices are estimates at 75% of the listed foreign-shop price.";
    }
    function renderRankings() {
        const heading = panel.querySelector("#tdro-ranking-heading");
        const note = panel.querySelector("#tdro-ranking-note");
        const container = panel.querySelector("#tdro-rankings");

        if (!selectedCountry) {
            heading.textContent = "Drug Rankings";
            note.textContent = "Select a destination to view its prices.";
            container.innerHTML =
                '<div class="tdro-muted">Waiting for the selected destination to be detected.</div>';
            return;
        }

        const country = getCountry(selectedCountry);
        const entries = countryRankings[selectedCountry] || [];

        heading.textContent = `${country?.name || selectedCountry} — Drug Rankings`;
        note.textContent =
            "Buying and selling prices are for this country; better alternatives are shown below.";

        if (!entries.length) {
            container.innerHTML =
                '<div class="tdro-muted">No drug prices are available for this destination.</div>';
            return;
        }

        container.innerHTML = entries.map(entry => {
            const medal = entry.rank === 1 ? "🥇" :
                entry.rank === 2 ? "🥈" :
                entry.rank === 3 ? "🥉" : "";

            let buyComparison = "-";
            if (entry.bestBuy &&
                entry.bestBuy.country.code !== selectedCountry &&
                entry.buyDifference > 0) {
                buyComparison = `💰 ${escapeHtml(entry.bestBuy.country.name)} sells for ` +
                    `${money(entry.buyDifference)} less per unit`;
            }

            let sellComparison = "-";
            if (entry.bestSell &&
                entry.bestSell.country.code !== selectedCountry &&
                entry.sellDifference > 0) {
                sellComparison = `💰 ${escapeHtml(entry.bestSell.country.name)} will buy for ` +
                    `${money(entry.sellDifference)} more per unit`;
            }

            return `
                <div class="tdro-drug-entry">
                    <div class="tdro-drug-title">
                        <strong>${escapeHtml(entry.name)}</strong>
                        <span class="tdro-rank">${medal} ${ordinal(entry.rank)}</span>
                    </div>
                    <div class="tdro-price-line">Buying: <strong>${money(entry.buy)}</strong></div>
                    <div class="tdro-compare">${buyComparison}</div>
                    <div class="tdro-price-line">Selling: <strong>${money(entry.sell)}</strong></div>
                    <div class="tdro-compare">${sellComparison}</div>
                </div>
            `;
        }).join("");
    }

    function renderRoutes() {
        const container = panel.querySelector("#tdro-routes");
        const count = panel.querySelector("#tdro-route-count");
        const requestedQuantity = getQuantity();

        const visibleRoutes = selectedCountry
            ? routes.filter(route =>
                route.origin.code === selectedCountry ||
                route.destination.code === selectedCountry
            )
            : routes;

        count.textContent = `${visibleRoutes.length} profitable routes`;

        if (!visibleRoutes.length) {
            container.innerHTML = selectedCountry
                ? '<div class="tdro-muted">No profitable routes involving this destination were found with the current price data.</div>'
                : '<div class="tdro-muted">Select a destination to filter routes.</div>';
            return;
        }

        container.innerHTML = visibleRoutes.slice(0, 30).map((route, index) => {
            const quantity = Math.max(1, Math.min(requestedQuantity, route.quantity));
            const totalProfit = route.profitPerUnit * quantity;
            const hourlyProfit = totalProfit / (route.minutes / 60);

            let buyStatus;
            if (route.buyStatus === "best") {
                buyStatus = '<div class="tdro-good">✓ Best buying price — no country is cheaper</div>';
            } else if (route.buyStatus === "cheaper") {
                const cheapest = getCheapestBuy(route.drug);
                const saving = cheapest ? route.buyPrice - cheapest.price : 0;
                buyStatus = cheapest
                    ? `<div class="tdro-warning">⚠ ${escapeHtml(cheapest.country.name)} sells for ${money(saving)} less per unit</div>`
                    : '<div class="tdro-muted">Buying price comparison unavailable</div>';
            } else {
                buyStatus = '<div class="tdro-muted">Buying price comparison unavailable</div>';
            }

            return `
                <div class="tdro-route-entry">
                    <div class="tdro-route-title">
                        <strong>#${index + 1} ${escapeHtml(route.drug)}</strong>
                        <span class="tdro-profit">${money(totalProfit)}</span>
                    </div>
                    <div class="tdro-route-path">
                        Buy in <strong>${escapeHtml(route.origin.name)}</strong>
                        at ${money(route.buyPrice)} →
                        sell in <strong>${escapeHtml(route.destination.name)}</strong>
                        for ${money(route.sellPrice)} (estimated)
                    </div>
                    ${buyStatus}
                    <div class="tdro-route-details">
                        ${quantity.toLocaleString("en-US")} unit(s) ·
                        ${money(route.profitPerUnit)} per unit ·
                        ${route.minutes.toFixed(1)} min/rotation
                    </div>
                    <div class="tdro-route-hourly">
                        Estimated earnings: <strong>${money(totalProfit)}</strong>
                        · <strong>${money(hourlyProfit)}/hour</strong>
                    </div>
                </div>
            `;
        }).join("");
    }

    function render() {
        if (!panel) return;
        panel.querySelector("#tdro-status").textContent = getDataStatus();
        renderRankings();
        renderRoutes();
    }

    function injectStyles() {
        if (document.getElementById("tdro-styles-v140")) return;

        const style = document.createElement("style");
        style.id = "tdro-styles-v140";
        style.textContent = `
            #${PANEL_ID} {
                box-sizing: border-box; width: 100%; max-width: 100%;
                margin: 10px 0 14px; padding: 10px;
                color: #f2f5f8; background: #171b20;
                border: 1px solid #48525e; border-radius: 8px;
                font: 12px/1.4 Arial, sans-serif; overflow-wrap: anywhere;
            }
            #${PANEL_ID} * { box-sizing: border-box; }
            #${PANEL_ID} h3 {
                margin: 0 0 5px; color: #fff; font-size: 14px; line-height: 1.3;
            }
            #${PANEL_ID} .tdro-muted { color: #c0c9d3; font-size: 11px; }
            #${PANEL_ID} .tdro-status {
                margin: 0 0 9px; color: #c0c9d3; font-size: 10px;
            }
            #${PANEL_ID} .tdro-section {
                margin-top: 10px; padding-top: 9px; border-top: 1px solid #48525e;
            }
            #${PANEL_ID} .tdro-drug-entry,
            #${PANEL_ID} .tdro-route-entry {
                margin: 0; padding: 7px 0; border-bottom: 1px solid #39424c;
            }
            #${PANEL_ID} .tdro-drug-entry:last-child,
            #${PANEL_ID} .tdro-route-entry:last-child { border-bottom: 0; }
            #${PANEL_ID} .tdro-drug-title,
            #${PANEL_ID} .tdro-route-title {
                display: flex; align-items: baseline; justify-content: space-between;
                gap: 8px; margin-bottom: 3px; color: #fff;
            }
            #${PANEL_ID} .tdro-rank {
                flex-shrink: 0; color: #f5d77a; font-weight: 700;
            }
            #${PANEL_ID} .tdro-price-line { color: #f2f5f8; margin-top: 2px; }
            #${PANEL_ID} .tdro-compare {
                min-height: 14px; color: #ffd166; font-size: 11px; margin: 1px 0 3px;
            }
            #${PANEL_ID} .tdro-route-path { color: #e0e6ed; margin: 3px 0; }
            #${PANEL_ID} .tdro-route-details {
                color: #c0c9d3; font-size: 10px; margin-top: 3px;
            }
            #${PANEL_ID} .tdro-route-hourly { color: #f2f5f8; margin-top: 3px; }
            #${PANEL_ID} .tdro-profit, #${PANEL_ID} .tdro-good {
                color: #8fe3a2; font-weight: 700;
            }
            #${PANEL_ID} .tdro-warning {
                color: #ffd166; margin-top: 3px; font-size: 11px;
            }
            #${PANEL_ID} .tdro-controls {
                display: flex; align-items: center; flex-wrap: wrap;
                gap: 6px; margin: 7px 0;
            }
            #${PANEL_ID} input {
                width: 70px; max-width: 35%; padding: 5px; color: #fff;
                background: #252c34; border: 1px solid #657180;
                border-radius: 5px; font-size: 12px;
            }
            #${PANEL_ID} button {
                padding: 5px 8px; color: #fff; background: #354250;
                border: 1px solid #657180; border-radius: 5px; font-size: 11px;
            }
        `;
        document.head.appendChild(style);
    }
    function findTravelInsertionTarget() {
        const elements = Array.from(document.querySelectorAll("h1, h2, h3, h4, p, label, div, span"));

        const heading = elements.find(element => {
            if (element.closest("#" + PANEL_ID)) return false;
            if (element.children.length > 3) return false;
            const text = normalizeKey(element.textContent);
            return text.includes("selectdestinationandtravelingmethod");
        });

        if (heading) return heading;

        const toggler = document.querySelector('button[class*="destDropdownToggler"]');
        if (toggler) {
            return toggler.closest("section") ||
                toggler.closest("div") ||
                toggler.parentElement;
        }

        return null;
    }

    function createPanel() {
        const existing = document.getElementById(PANEL_ID);
        if (existing) {
            panel = existing;
            return panel;
        }

        injectStyles();

        panel = document.createElement("section");
        panel.id = PANEL_ID;
        panel.innerHTML = `
            <h3>Drug Trade Route Optimizer</h3>
            <div id="tdro-status" class="tdro-status">Loading price data…</div>

            <div class="tdro-controls">
                <label for="tdro-quantity">Trade quantity:</label>
                <input id="tdro-quantity" type="number" min="1" max="10000"
                    step="1" value="${getSavedQuantity()}">
                <button id="tdro-refresh" type="button">Refresh prices</button>
            </div>

            <div class="tdro-section">
                <h3 id="tdro-ranking-heading">Drug Rankings</h3>
                <div id="tdro-ranking-note" class="tdro-muted">
                    Select a destination to view its prices.
                </div>
                <div id="tdro-rankings"></div>
            </div>

            <div class="tdro-section">
                <h3>Optimized Trade Routes</h3>
                <div id="tdro-route-count" class="tdro-muted">Calculating routes…</div>
                <div id="tdro-routes"></div>
            </div>
        `;

        const target = findTravelInsertionTarget();
        if (target && target.parentElement) {
            target.insertAdjacentElement("afterend", panel);
        } else {
            const main = document.querySelector("main") ||
                document.querySelector("#mainContainer") ||
                document.body;
            main.appendChild(panel);
        }

        panel.querySelector("#tdro-refresh").addEventListener("click", () => {
            refresh(true);
        });

        panel.querySelector("#tdro-quantity").addEventListener("input", event => {
            const quantity = saveQuantity(event.target.value);
            event.target.value = quantity;
            routes = buildRoutes();
            renderRoutes();
        });

        return panel;
    }

    async function refresh(force) {
        if (loading) return;

        loading = true;
        errorMessage = "";
        render();

        const cached = readCache();
        const cacheAge = cached?.timestamp
            ? Date.now() - cached.timestamp
            : Infinity;

        let yataData = cached?.yata || null;
        let promData = cached?.prom || null;

        if (!force && cacheAge < CACHE_TTL && yataData && promData) {
            allItems = buildCombinedItems(yataData, promData);
            countryRankings = buildCountryRankings();
            routes = buildRoutes();
            lastRefresh = cached.timestamp;
            loading = false;
            render();
            return;
        }

        try {
            const results = await Promise.allSettled([
                requestJson(YATA_URL),
                requestJson(PROM_URL)
            ]);

            if (results[0].status === "fulfilled") yataData = results[0].value;
            if (results[1].status === "fulfilled") promData = results[1].value;

            const freshFeedReceived = results.some(
                result => result.status === "fulfilled"
            );

            if (!yataData && !promData) {
                throw new Error("Both price feeds failed.");
            }

            if (!freshFeedReceived && cacheAge > STALE_TTL) {
                throw new Error("Price feeds failed and cached data is too old.");
            }

            if (freshFeedReceived) {
                writeCache(yataData, promData);
                lastRefresh = Date.now();
            } else {
                lastRefresh = cached?.timestamp || 0;
            }

            allItems = buildCombinedItems(yataData, promData);

            if (!Object.values(allItems).some(items => Object.keys(items || {}).length)) {
                throw new Error("No recognized drug prices found in the feeds.");
            }

            countryRankings = buildCountryRankings();
            routes = buildRoutes();
        } catch (error) {
            log("Refresh failed:", error);

            if (cached?.yata || cached?.prom) {
                allItems = buildCombinedItems(cached.yata, cached.prom);
                countryRankings = buildCountryRankings();
                routes = buildRoutes();
                lastRefresh = cached.timestamp || 0;
                errorMessage = "Live refresh failed; showing cached prices.";
            } else {
                errorMessage = "Could not load prices. Check your connection and try Refresh prices.";
            }
        } finally {
            loading = false;
            updateSelectedCountry();
            render();
        }
    }

    function initialize() {
        if (!isTravelScreen()) return;

        createPanel();
        selectedCountry = detectSelectedCountry();

        // Load cached prices first; the refresh function uses the cache when fresh.
        refresh(false);

        if (observer) observer.disconnect();

        observer = new MutationObserver(() => {
            if (!document.getElementById(PANEL_ID)) {
                panel = null;
                createPanel();
                render();
            }
            updateSelectedCountry();
        });

        observer.observe(document.body, {
            childList: true,
            subtree: true,
            attributes: true,
            attributeFilter: [
                "aria-pressed", "aria-selected", "aria-label",
                "title", "class", "data-selected",
                "data-country", "data-destination"
            ]
        });

        // Fallback for React/UI state changes that aren't exposed as attributes.
        if (destinationCheckTimer) clearInterval(destinationCheckTimer);
        destinationCheckTimer = setInterval(() => {
            if (!document.getElementById(PANEL_ID)) return;
            updateSelectedCountry();

            // Price feeds refresh at most once per cache interval automatically.
            if (!loading && Date.now() - lastRefresh >= CACHE_TTL) {
                refresh(false);
            }
        }, 1500);
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", initialize, { once: true });
    } else {
        initialize();
    }
})();
